import crypto from 'node:crypto';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { config } from '../../config.js';
import { badRequest } from '../http.js';

/**
 * Drive files live flat under <DOCS_DIR>/drive/<storageKey>. The key is random and generated by the
 * server; user-supplied names never reach the file system, so renames and moves never touch the disk and
 * path traversal is impossible by construction.
 */
export const driveDir = config.drive.dir;
export const incomingDir = path.join(config.docs.dir, '.incoming');

fs.mkdirSync(driveDir, { recursive: true });
fs.mkdirSync(incomingDir, { recursive: true });

const KEY = /^[a-f0-9]{32}$/;

export const newStorageKey = () => crypto.randomBytes(16).toString('hex');

export const storagePath = (key: string) => {
  if (!KEY.test(key)) throw badRequest('INVALID_STORAGE_KEY');
  return path.join(driveDir, key);
};

/** Moves a verified upload (spooled in .incoming) into the store under a fresh key. */
export const adoptUpload = async (tmpPath: string) => {
  const key = newStorageKey();
  await fsp.mkdir(driveDir, { recursive: true });
  await fsp.rename(tmpPath, storagePath(key));
  return key;
};

/** Copies any file into the store under a fresh key (copies, imports, version restores). */
export const copyIntoStore = async (srcPath: string) => {
  const key = newStorageKey();
  await fsp.mkdir(driveDir, { recursive: true });
  await fsp.copyFile(srcPath, storagePath(key), fs.constants.COPYFILE_EXCL);
  return key;
};

/** Removes stored files; already-missing files are fine. Returns the number of bytes freed. */
export const removeStored = async (keys: (string | null | undefined)[]) => {
  let bytes = 0;
  for (const key of keys) {
    if (!key || !KEY.test(key)) continue;
    const p = storagePath(key);
    try {
      const st = await fsp.stat(p);
      await fsp.unlink(p);
      bytes += st.size;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err;
    }
  }
  return bytes;
};
